from collections import deque
def comps(a):
    H,W=a.shape; seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if (r,c) in seen: continue
            v=a[r][c]; q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    n=(y+dy,x+dx)
                    if 0<=n[0]<H and 0<=n[1]<W and n not in seen and a[n]==v:
                        seen.add(n); q.append(n)
            out.append((v,cells))
    return out
